import itertools
import json

def solve_puzzle():
    houses = [1, 2]  # House numbers from left (1) to right (2)

    # Attributes and their values
    attributes = {
        "Name": ["Eric", "Arnold"],
        "style of house": ["victorian", "colonial"],
        "heights": ["very short", "short"],
        "level of education": ["associate", "high school"],
    }

    # Generate all permutations for each attribute mapping value -> house
    perms = {attr: list(itertools.permutations(houses)) for attr in attributes}

    solutions = []
    for name_perm in perms["Name"]:
        name_map = {attributes["Name"][i]: name_perm[i] for i in range(len(name_perm))}
        # Early pruning from Clue 1: the person who is short is directly left of Eric
        # This implies Eric cannot be in house 1
        if name_map["Eric"] == 1:
            continue

        for style_perm in perms["style of house"]:
            style_map = {attributes["style of house"][i]: style_perm[i] for i in range(len(style_perm))}
            # Clue 2: Victorian is in the first house
            if style_map["victorian"] != 1:
                continue

            for height_perm in perms["heights"]:
                height_map = {attributes["heights"][i]: height_perm[i] for i in range(len(height_perm))}
                # Clue 1: short is directly left of Eric
                if not (height_map["short"] + 1 == name_map["Eric"]):
                    continue

                for edu_perm in perms["level of education"]:
                    edu_map = {attributes["level of education"][i]: edu_perm[i] for i in range(len(edu_perm))}
                    # Clue 3: short <-> associate are the same person (same house)
                    if height_map["short"] != edu_map["associate"]:
                        continue

                    # If all constraints satisfied, construct house-wise solution
                    house_rows = []
                    for h in sorted(houses):
                        name = next(v for v, pos in name_map.items() if pos == h)
                        style = next(v for v, pos in style_map.items() if pos == h)
                        height = next(v for v, pos in height_map.items() if pos == h)
                        edu = next(v for v, pos in edu_map.items() if pos == h)
                        house_rows.append([str(h), name, style, height, edu])

                    solutions.append(house_rows)

    # Prefer the unique solution if exists; otherwise take the first found.
    final_rows = solutions[0] if solutions else []

    result = {
        "solution": {
            "header": ["House", "Name", "style of house", "heights", "level of education"],
            "rows": final_rows
        }
    }
    return result

if __name__ == "__main__":
    solution = solve_puzzle()
    print(json.dumps(solution, ensure_ascii=False))
